from pathlib import Path
import json,shutil

HERE=Path(__file__).resolve().parent;SIM=HERE.parent;ROOT=SIM.parent
data=json.loads((HERE/'outputs/validation_r2_analysis/aggregate.json').read_text(encoding='utf-8'))
def get(cond,method):return next((x for x in data if x['condition']==cond and x['method']==method),None)
full=get('tracking','shared');free=get('tracking','shared_free_waist');base=get('tracking','adaptive');severe=get('severe','shared')
names={'adaptive':'直接跟踪','stable':'仅腰部稳定','shared_free_waist':'去掉腰部稳定','shared_no_contact':'去掉支撑反馈','shared_no_frame':'去掉坐标补偿','shared':'完整方法'}
rows=''
for method,label in names.items():
    values=[]
    for cond in ['clean','tracking','severe']:
        r=get(cond,method);values.append(f"{r['success']}/{r['n']}"if r else '—')
    a=get('tracking',method)
    rows+=f"<tr><th>{label}</th>"+''.join(f'<td>{v}</td>'for v in values)+f"<td>{a['waist_peak_to_peak_deg']:.2f}°</td><td>{a['hand_rmse_mm']:.1f} mm</td></tr>"
